function getSettings(){return Object.fromEntries(Object.entries(opts).map(([k,e])=>[k, e.type==='checkbox'?e.checked:e.value]));}
function godModeEnabled(){return !!opts.godMode?.checked;}
function saveSettings(){localStorage.astraLanderSettings=JSON.stringify(getSettings());}
function loadSettings(){try{ if(localStorage.astraSettingsVersion!=='5'){ localStorage.removeItem('astraLanderSettings'); localStorage.astraSettingsVersion='5'; } let s=JSON.parse(localStorage.astraLanderSettings||'{}'); for(const [k,v] of Object.entries(s)){ if(opts[k]){ if(opts[k].type==='checkbox') opts[k].checked=!!v; else opts[k].value=v; } }}catch{}}
loadSettings(); Object.values(opts).forEach(e=>e.addEventListener('change',()=>{saveSettings();if(e===opts.godMode&&e.checked)godModeUsedThisRun=true;updateGroundUI();}));

const LEADERBOARD_KEY='astraOneTankLeaderboardV1';
