const leaderboardSort=(a,b)=>b.landings-a.landings||b.score-a.score||String(a.date).localeCompare(String(b.date));
function loadLeaderboard(){try{const raw=JSON.parse(localStorage.getItem(LEADERBOARD_KEY)||'[]');if(!Array.isArray(raw))return[];return raw.map(e=>({name:String(e.name||'PILOT').slice(0,16),landings:Math.max(0,Number(e.landings)||0),score:Math.max(0,Number(e.score)||0),difficulty:String(e.difficulty||'normal'),date:String(e.date||'')})).sort(leaderboardSort).slice(0,10);}catch{return[];}}
function renderLeaderboard(){const board=loadLeaderboard();els.leaderboardList.replaceChildren();board.forEach((entry,index)=>{const li=document.createElement('li'),rank=document.createElement('b'),pilot=document.createElement('span'),result=document.createElement('span');rank.textContent=`#${index+1}`;pilot.textContent=entry.name;result.textContent=`${entry.landings} landing${entry.landings===1?'':'s'} · ${entry.score} pts · ${entry.difficulty}`;li.append(rank,pilot,result);els.leaderboardList.append(li);});els.noScores.classList.toggle('hidden',board.length>0);els.currentRun.textContent=`Current run: ${landings} landing${landings===1?'':'s'} · ${score} points`;return board;}
function isOneTankRun(){const s=getSettings();return s.missionType==='endless'&&s.fuelMode==='limited'&&!godModeUsedThisRun&&!godModeEnabled();}
function qualifiesForLeaderboard(){if(!isOneTankRun()||landings<1||runSubmitted)return false;const board=loadLeaderboard(),candidate={landings,score,date:''};return board.length<10||leaderboardSort(candidate,board[board.length-1])<0;}
function offerLeaderboardEntry(){const qualifies=qualifiesForLeaderboard();els.scoreEntry.classList.toggle('hidden',!qualifies);if(qualifies){els.pilotName.value=localStorage.astraPilotName||'';setTimeout(()=>els.pilotName.focus(),80);}renderLeaderboard();}
function saveCurrentScore(name=els.pilotName.value){name=String(name||'').trim().replace(/\s+/g,' ').slice(0,16);if(!name||!qualifiesForLeaderboard())return false;localStorage.astraPilotName=name;const board=loadLeaderboard();board.push({name,landings,score,difficulty:getSettings().difficulty,date:new Date().toISOString()});localStorage.setItem(LEADERBOARD_KEY,JSON.stringify(board.sort(leaderboardSort).slice(0,10)));runSubmitted=true;els.scoreEntry.classList.add('hidden');renderLeaderboard();showLeaderboard(true);return true;}
