function setThrustMode(mode){if(!THRUST_LEVELS[mode])return false;thrustMode=mode;localStorage.astraThrustMode=mode;document.querySelectorAll('[data-thrust-mode]').forEach(button=>button.classList.toggle('active',button.dataset.thrustMode===mode));els.thrust.textContent=`THRUST · ${THRUST_LEVELS[mode].label}`;return true;}

class AudioEngine{
  constructor(){this.ctx=null;this.master=null;this.thrust=null;this.thrustGain=null;this.musicOn=false;this.musicStage=0;this.musicTempo=260;}
  init(){ if(this.ctx) return; const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return; this.ctx=new AC(); this.master=this.ctx.createGain(); this.master.gain.value=.42; this.master.connect(this.ctx.destination); this.makeThrust(); }
  makeThrust(){ if(!this.ctx) return; const noise=this.ctx.createBufferSource(); const buf=this.ctx.createBuffer(1,this.ctx.sampleRate*2,this.ctx.sampleRate); const data=buf.getChannelData(0); for(let i=0;i<data.length;i++) data[i]=(Math.random()*2-1)*(1-i/data.length*.25); noise.buffer=buf; noise.loop=true; const filter=this.ctx.createBiquadFilter(); filter.type='lowpass'; filter.frequency.value=420; const gain=this.ctx.createGain(); gain.gain.value=0; noise.connect(filter); filter.connect(gain); gain.connect(this.master); noise.start(); this.thrust=noise; this.thrustGain=gain; this.thrustFilter=filter; }
  resume(){this.init(); if(this.ctx?.state==='suspended') this.ctx.resume();}
  setThrust(on,power=1){ if(!this.thrustGain) return; const t=this.ctx.currentTime; this.thrustGain.gain.cancelScheduledValues(t); this.thrustGain.gain.linearRampToValueAtTime(on?.16*power:0,t+.045); this.thrustFilter.frequency.setTargetAtTime(on?lerp(260,720,power):260,t,.05); }
  beep(freq=440,dur=.12,type='sine',gain=.12){ if(!getSettings().sfxToggle) return; this.resume(); if(!this.ctx) return; const o=this.ctx.createOscillator(), g=this.ctx.createGain(); o.type=type; o.frequency.value=freq; g.gain.value=0; o.connect(g); g.connect(this.master); const t=this.ctx.currentTime; g.gain.linearRampToValueAtTime(gain,t+.01); g.gain.exponentialRampToValueAtTime(.0001,t+dur); o.frequency.exponentialRampToValueAtTime(freq*.55,t+dur); o.start(t); o.stop(t+dur+.02); }
  noiseHit(dur=.45,gain=.25){ if(!getSettings().sfxToggle) return; this.resume(); if(!this.ctx) return; const src=this.ctx.createBufferSource(); const buf=this.ctx.createBuffer(1,this.ctx.sampleRate*dur,this.ctx.sampleRate); const d=buf.getChannelData(0); for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,2); src.buffer=buf; const f=this.ctx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=160; const g=this.ctx.createGain(); g.gain.value=gain; src.connect(f); f.connect(g); g.connect(this.master); src.start(); }
  setMusicStage(stage=0){stage=Math.max(0,Math.floor(stage));if(stage===this.musicStage)return;this.musicStage=stage;if(this.musicOn){this.musicOn=false;clearInterval(musicTimer);musicTimer=null;this.music(true);}}
  music(start){ if(start===this.musicOn) return; this.resume(); this.musicOn=start; if(!start){clearInterval(musicTimer); musicTimer=null; return;} const themes=[[110,130.81,164.81,196,220,261.63,329.63],[98,123.47,146.83,196,233.08,293.66,392],[130.81,155.56,185,220,277.18,329.63,440],[82.41,110,138.59,164.81,207.65,246.94,329.63]],scale=themes[this.musicStage%themes.length],wave=['triangle','square','sawtooth','triangle'][this.musicStage%4];this.musicTempo=Math.max(155,260-Math.min(8,this.musicStage)*13);let step=0; musicTimer=setInterval(()=>{ if(!getSettings().musicToggle||paused||!running) return; const base=scale[step%scale.length],accent=step%(8-Math.min(3,this.musicStage%4))===0; this.beep(base*(accent?2:1),.16,wave,.032); if(step%4===0)this.beep(base/2,.26,'sine',.022);if(this.musicStage>1&&step%6===3)this.beep(base*1.5,.09,'triangle',.018);step++;},this.musicTempo); }
}
audio=new AudioEngine();

