function groundY(x){ if(!terrain.length) return worldH-safeBottom; for(let i=1;i<terrain.length;i++){ const a=terrain[i-1],b=terrain[i]; if(x<=b.x){ const t=(x-a.x)/(b.x-a.x); return lerp(a.y,b.y,t); } } return terrain[terrain.length-1].y; }
