function exitRocket(){if(!ship?.landed||pilot||gameOver||paused)return false;const side=ship.x<worldW-70?1:-1;pilot={x:ship.x+side*38,y:groundY(ship.x+side*38)-16,vx:0,vy:0,facing:side,onGround:true,health:pilotMaxHealth,invulnerable:0};clearAllControls();audio.beep(520,.12,'square',.08);haptic(18);updateGroundUI();return true;}
