function spawnCreatureAt(x,kind){kind=CREATURE_TYPES[kind]?kind:(kills>=7&&Math.random()<.22?'brute':kills>=3&&Math.random()<.34?'sprinter':'crawler');const type=CREATURE_TYPES[kind],enemy={x:clamp(x,24,worldW-24),y:0,kind,hp:type.hp,maxHp:type.hp,speed:type.speed,size:type.size,reward:type.reward,points:type.points,color:type.color,phase:rand(0,TAU),hit:0};enemy.y=groundY(enemy.x)-enemy.size;enemies.push(enemy);return enemy;}
