const AIR_TYPES={scout:{hp:2,size:13,speed:.030,points:600,color:'#7df9ff',fire:1800},fighter:{hp:4,size:17,speed:.024,points:1100,color:'#ff5bb8',fire:1450},gunship:{hp:8,size:24,speed:.017,points:2200,color:'#ffb23d',fire:1100},boss:{hp:30,size:38,speed:.012,points:8000,color:'#ff385f',fire:780}};
