function damageShip(amount=1,reason='enemy fire'){if(godModeEnabled()){shipHull=shipMaxHull;shipShield=shipMaxShield;shipHitCooldown=180;fuelBursts.push({x:ship.x,y:ship.y-42,text:'GOD MODE · NO DAMAGE',life:700,color:'#ffd36b'});return true;}if(shipHitCooldown>0||gameOver)return false;shipHitCooldown=700;if(shipShield>0){shipShield=Math.max(0,shipShield-1);fuelBursts.push({x:ship.x,y:ship.y-42,text:'SHIELD IMPACT',life:900,color:'#7df9ff'});audio.beep(210,.18,'sawtooth',.1);camera.shake=7;return true;}shipHull=Math.max(0,shipHull-amount);fuelBursts.push({x:ship.x,y:ship.y-42,text:`HULL HIT · ${shipHull}/${shipMaxHull}`,life:1100,color:'#ff5b72'});audio.noiseHit(.25,.13);camera.shake=10;haptic(28);if(shipHull<=0){explode();endMessage('SHOT DOWN',`${reason}. Sector ${padCycle+1} · ${landings} landings · ${bossesDefeated} bosses defeated.`);}return true;}
function fireRocketCannon(target=null,source='cannon'){const god=godModeEnabled(),damage=god?4:cannonDamage;if((!cannonUnlocked&&!god)||pilot||ship.landed||gameOver||cannonCooldown>0)return false;cannonCooldown=damage>=3?245:135;const angle=target?Math.atan2(target.y-ship.y,target.x-ship.x):ship.angle-Math.PI/2,speed=damage>=3?1.18:.92;rocketShots.push({x:ship.x+Math.cos(angle)*28,y:ship.y+Math.sin(angle)*28,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,angle,life:1500,damage:source==='drone'?1:damage,pierce:damage>=3?2:0,target:source==='drone'?target:null,source});audio.beep(damage>=3?1180:940,.055,damage>=3?'sawtooth':'square',.045);return true;}
function updateAirCombat(dt){cannonCooldown=Math.max(0,cannonCooldown-dt);droneCooldown=Math.max(0,droneCooldown-dt);shipHitCooldown=Math.max(0,shipHitCooldown-dt);if((input.cannon||input.keys.KeyC)&&(cannonUnlocked||godModeEnabled()))fireRocketCannon();if(guardianDrone&&!ship.landed&&!pilot&&droneCooldown<=0&&airEnemies.length){droneCooldown=580;const target=airEnemies.reduce((a,b)=>Math.hypot(a.x-ship.x,a.y-ship.y)<Math.hypot(b.x-ship.x,b.y-ship.y)?a:b);const saved=cannonCooldown;cannonCooldown=0;fireRocketCannon(target,'drone');cannonCooldown=Math.max(saved,90);}if(campaignTier>=2&&!ship.landed&&!pilot){airSpawnCooldown-=dt;const maxAir=Math.min(7,1+Math.floor(campaignTier/2));if(airSpawnCooldown<=0&&airEnemies.filter(e=>!e.boss).length<maxAir){const roll=Math.random(),kind=campaignTier>=6&&roll>.74?'gunship':campaignTier>=3&&roll>.42?'fighter':'scout';spawnAirEnemy(kind);airSpawnCooldown=Math.max(900,3900-campaignTier*210)+rand(0,1000);}}for(const enemy of airEnemies){enemy.hit=Math.max(0,enemy.hit-dt);enemy.phase+=dt*.004;if(!ship.landed&&!pilot){const desiredX=ship.x+Math.sin(enemy.phase)*Math.min(260,140+enemy.size*3),desiredY=ship.y-110+Math.cos(enemy.phase*.73)*90;enemy.x+=clamp(desiredX-enemy.x,-1,1)*enemy.speed*dt;enemy.y+=clamp(desiredY-enemy.y,-1,1)*enemy.speed*.72*dt;enemy.y=clamp(enemy.y,80,groundY(enemy.x)-100);enemy.fireCooldown-=dt;if(enemy.fireCooldown<=0){const a=Math.atan2(ship.y-enemy.y,ship.x-enemy.x),speed=enemy.boss?.33:.27;enemyShots.push({x:enemy.x,y:enemy.y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:3600,damage:enemy.boss?2:1,color:enemy.color});enemy.fireCooldown=enemy.fireRate+rand(0,500);}}}for(let i=rocketShots.length-1;i>=0;i--){const shot=rocketShots[i];if(shot.target&&airEnemies.includes(shot.target)){const desired=Math.atan2(shot.target.y-shot.y,shot.target.x-shot.x),delta=(desired-shot.angle+Math.PI*3)%TAU-Math.PI;shot.angle+=clamp(delta,-.006*dt,.006*dt);const speed=Math.hypot(shot.vx,shot.vy);shot.vx=Math.cos(shot.angle)*speed;shot.vy=Math.sin(shot.angle)*speed;}shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;shot.life-=dt;let remove=shot.life<=0||shot.x<0||shot.x>worldW||shot.y<0||shot.y>worldH;for(let ei=airEnemies.length-1;ei>=0&&!remove;ei--){const enemy=airEnemies[ei];if(Math.hypot(enemy.x-shot.x,enemy.y-shot.y)<enemy.size+6){enemy.hp-=shot.damage;enemy.hit=110;if(enemy.hp<=0)killAirEnemy(enemy,ei,shot.source==='cannon'&&(cannonDamage>=3||godModeEnabled())?'rail':shot.source);if(shot.pierce>0)shot.pierce--;else remove=true;}}if(remove)rocketShots.splice(i,1);}for(let i=enemyShots.length-1;i>=0;i--){const shot=enemyShots[i];shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;shot.life-=dt;if(!ship.landed&&!pilot&&Math.hypot(shot.x-ship.x,shot.y-ship.y)<24){damageShip(shot.damage,'Hostile ships destroyed the rocket');enemyShots.splice(i,1);continue;}if(shot.life<=0||shot.x<0||shot.x>worldW||shot.y<0||shot.y>worldH)enemyShots.splice(i,1);}}
function adjustAim(delta){if(!pilot||gameOver)return false;weaponAim=clamp(weaponAim+delta,-.78,.78);audio.beep(520+Math.round(-weaponAim*180),.035,'triangle',.025);updateGroundUI();return true;}
function killCreature(enemy,index,source='bullet',critical=false){enemies.splice(index,1);kills++;if(enemy.boss)bossesDefeated++;const now=performance.now();combatCombo=now-lastKillAt<2200?Math.min(8,combatCombo+1):1;lastKillAt=now;const weaponBonus=source==='grenade'?100:source==='bomb'?125:source==='missile'?200:0,reward=enemy.reward+Math.min(10,(combatCombo-1)*2),points=enemy.points*combatCombo+(critical?150:0)+weaponBonus;if(getSettings().fuelMode==='limited')ship.fuel+=reward;score+=points;fuelBursts.push({x:enemy.x,y:enemy.y-14,text:`+${reward} FUEL · +${points} PTS${critical?' · CRITICAL!':''}`,life:1250,color:critical?'#ffd36b':'#59ff91'});if(kills%5===0){grenadeAmmo=Math.min(5,grenadeAmmo+1);if(pilot)pilot.health=Math.min(pilotMaxHealth,pilot.health+1);if(getSettings().fuelMode==='limited')ship.fuel+=10;fuelBursts.push({x:enemy.x,y:enemy.y-34,text:'SUPPLY BONUS · +10 FUEL · +1 GRENADE',life:1600,color:'#7df9ff'});}for(let i=0;i<18;i++)particles.push({x:enemy.x,y:enemy.y,vx:rand(-.15,.15),vy:rand(-.20,.05),life:rand(300,700),r:rand(2,5),g:.00016,color:enemy.color});audio.beep(210+combatCombo*45,.15,'square',.08);haptic(14);if(enemy.boss&&landings>=5&&bossesDefeated>=1){if(DEMO_MODE)setTimeout(showDemoComplete,450);else if(PURCHASE_GATE&&!fullGameUnlocked)setTimeout(showPurchaseGate,450);}}
function shootPilot(){if(!pilot||shootCooldown>0||gameOver)return false;const god=godModeEnabled();shootCooldown=god?145:pilotFireRate;const speed=.72,cos=Math.cos(weaponAim),sin=Math.sin(weaponAim);bullets.push({x:pilot.x+pilot.facing*12*cos,y:pilot.y-10+12*sin,vx:pilot.facing*speed*cos,vy:speed*sin,life:1100,damage:god?3:pilotDamage});audio.beep(880,.07,'square',.055);haptic(8);return true;}
function throwGrenade(){const god=godModeEnabled();if(!pilot||grenadeCooldown>0||(!god&&grenadeAmmo<=0)||gameOver)return false;grenadeCooldown=650;if(!god)grenadeAmmo--;const cos=Math.cos(weaponAim),sin=Math.sin(weaponAim);grenades.push({x:pilot.x+pilot.facing*12,y:pilot.y-18,vx:pilot.facing*.34*cos,vy:-.31+sin*.18,life:950,bounces:0,phase:0});audio.beep(260,.09,'square',.07);haptic(12);updateGroundUI();return true;}
function explodeGrenade(grenade){camera.shake=10;audio.noiseHit(.32,.18);audio.beep(95,.25,'sawtooth',.11);haptic([24,18,35]);for(let i=0;i<34;i++)particles.push({x:grenade.x,y:grenade.y,vx:rand(-.24,.24),vy:rand(-.26,.18),life:rand(350,850),r:rand(2,7),g:.0002,color:Math.random()<.5?'#c9ff68':'#ffb23d'});for(let ei=enemies.length-1;ei>=0;ei--){const enemy=enemies[ei],distance=Math.hypot(enemy.x-grenade.x,enemy.y-grenade.y);if(distance<100){enemy.hp-=distance<55?4:2;enemy.hit=140;if(enemy.hp<=0)killCreature(enemy,ei,'grenade',false);}}}
function applyMilestoneUpgrade(milestone){campaignTier=Math.max(campaignTier,milestone/5);bombCapacity=3+campaignTier;missileCapacity=2+campaignTier*2;extraLives++;bombAmmo=Math.min(bombCapacity,bombAmmo+1);const points={5:2500,10:4000,15:5000,20:6000,25:7500,30:9000,35:11000,40:13500,45:16000,50:25000}[milestone]||0;score+=points;if(milestone===5){homingUnlocked=true;localStorage.astraHomingUnlocked='1';missileAmmo=Math.min(missileCapacity,missileAmmo+3);}else missileAmmo=Math.min(missileCapacity,missileAmmo+2);if(milestone===10)cannonUnlocked=true;if(milestone===15){shipMaxShield=2;shipShield=2;shipMaxHull=4;shipHull=4;}if(milestone===20){pilotDamage=2;pilotFireRate=175;}if(milestone===25){bombPower=1.45;bombAmmo=Math.min(bombCapacity,bombAmmo+1);}if(milestone===30){engineBoost=1.16;fuelEfficiency=.85;}if(milestone===35)guardianDrone=true;if(milestone===40){cannonDamage=3;cannonUnlocked=true;}if(milestone===45){pilotMaxHealth=4;pilotFireRate=145;if(pilot)pilot.health=pilotMaxHealth;}if(milestone===50){shipMaxShield=4;shipShield=4;shipMaxHull=5;shipHull=5;cannonDamage=4;bombPower=1.65;pilotDamage=3;engineBoost=1.24;fuelEfficiency=.78;guardianDrone=true;}return points;}
function milestoneSpec(milestone){return MILESTONES[milestone]||{title:'QUANTUM CHECKPOINT SECURED',button:'CONTINUE CAMPAIGN',boss:`ASTRAL SOVEREIGN Ω-${milestone/5}`,air:true,text:'Endless-tier reinforcements delivered.'};}
function spawnMilestoneBoss(milestone){const spec=milestoneSpec(milestone),tier=milestone/5,target=getNextPad()||pads.find(p=>!p.used)||pads[0];if(spec.air)return spawnAirEnemy('boss',{name:spec.boss,hp:24+tier*8,points:6500+tier*1200,x:target.x+target.w/2,y:Math.max(150,target.y-rand(300,460)),boss:true});const enemy=spawnCreatureAt(target.x+target.w/2+(Math.random()<.5?-1:1)*(target.w/2+55),'boss');Object.assign(enemy,{name:spec.boss,boss:true,hp:20+tier*7,maxHp:20+tier*7,points:5500+tier*1100,reward:70+tier*5,color:currentWorldTheme().hot});return enemy;}
function showMilestoneReward(milestone){const spec=milestoneSpec(milestone);if(lastRewardMilestone>=milestone)return false;lastRewardMilestone=milestone;applyMilestoneUpgrade(milestone);spawnMilestoneBoss(milestone);saveSectorCheckpoint();els.rewardMilestone.textContent=`${milestone}-LANDING REWARD · TIER ${milestone/5} · EXTRA LIFE +1`;els.rewardTitle.textContent=spec.title;els.rewardText.textContent=`${spec.text} CHECKPOINT SAVED at landing ${milestone}. Supplies increased to ${bombAmmo}/${bombCapacity} bombs and ${missileAmmo}/${missileCapacity} homing missiles. WARNING: ${spec.boss} now guards ${currentWorldTheme().name}.`;els.rewardContinue.textContent=spec.button;const artMilestone=MILESTONES[milestone]?milestone:50;els.rewardImage.src=`assets/reward-${String(artMilestone).padStart(2,'0')}.svg`;els.rewardImage.alt=`Landing ${milestone} upgrade: ${spec.title}`;els.rewardPopup.classList.remove('hidden');resumeAfterReward=running&&!paused&&!gameOver;if(resumeAfterReward)paused=true;audio.beep(760+milestone*8,.32,'triangle',.13);setTimeout(()=>audio.beep(1080+milestone*7,.42,'sawtooth',.1),140);haptic([35,35,45,35,80]);updateGroundUI();return true;}
function showFiveLandingReward(){return showMilestoneReward(5);}
function closeFiveLandingReward(){els.rewardPopup.classList.add('hidden');if(resumeAfterReward&&!gameOver){paused=false;last=performance.now();}resumeAfterReward=false;updateGroundUI();}
function dropRocketBomb(){const god=godModeEnabled();if(pilot||ship.landed||gameOver||bombCooldown>0||(!god&&bombAmmo<=0))return false;if(!god)bombAmmo--;bombCooldown=420;rocketBombs.push({x:ship.x-Math.sin(ship.angle)*18,y:ship.y+Math.cos(ship.angle)*25,vx:ship.vx/16.67,vy:ship.vy/16.67+.045,life:4000,phase:0});audio.beep(190,.08,'square',.07);haptic(11);updateGroundUI();return true;}
function findHomingTarget(x,y){return [...airEnemies,...enemies,...obstacles.filter(o=>o.kind!=='gravity')].reduce((best,e)=>!best||Math.hypot(e.x-x,e.y-y)<Math.hypot(best.x-x,best.y-y)?e:best,null);}
function launchHomingMissile(){const god=godModeEnabled();if(pilot||ship.landed||gameOver||(!homingUnlocked&&!god)||missileCooldown>0||(!god&&missileAmmo<=0))return false;if(!god)missileAmmo--;missileCooldown=620;const target=findHomingTarget(ship.x,ship.y),angle=target?Math.atan2(target.y-ship.y,target.x-ship.x):ship.angle-Math.PI/2;homingMissiles.push({x:ship.x+Math.cos(angle)*25,y:ship.y+Math.sin(angle)*25,vx:Math.cos(angle)*.5,vy:Math.sin(angle)*.5,angle,life:3600,target});audio.beep(720,.12,'sawtooth',.075);haptic([10,22,10]);updateGroundUI();return true;}
function explodeRocketWeapon(item,kind){const bomb=kind==='bomb',effectiveBombPower=godModeEnabled()?1.65:bombPower,radius=(bomb?125:95)*(bomb?effectiveBombPower:1),inner=(bomb?72:52)*(bomb?effectiveBombPower:1),source=bomb?'bomb':'missile';camera.shake=bomb?13:9;audio.noiseHit(bomb?.42:.28,bomb?.22:.16);audio.beep(bomb?78:125,bomb?.32:.22,'sawtooth',.13);haptic(bomb?[32,18,42]:[20,14,28]);for(let i=0;i<(bomb?42:30);i++)particles.push({x:item.x,y:item.y,vx:rand(-.28,.28),vy:rand(-.3,.17),life:rand(380,900),r:rand(2,8),g:.0002,color:Math.random()<.5?(bomb?'#ff743d':'#7df9ff'):(bomb?'#ffd36b':'#ff4fba')});for(let ei=enemies.length-1;ei>=0;ei--){const enemy=enemies[ei],distance=Math.hypot(enemy.x-item.x,enemy.y-item.y);if(distance<radius){enemy.hp-=(distance<inner?5:3)*(bomb?effectiveBombPower:1);enemy.hit=150;if(enemy.hp<=0)killCreature(enemy,ei,source,false);}}for(let ai=airEnemies.length-1;ai>=0;ai--){const enemy=airEnemies[ai],distance=Math.hypot(enemy.x-item.x,enemy.y-item.y);if(distance<radius){enemy.hp-=(distance<inner?5:3)*(bomb?effectiveBombPower:1);enemy.hit=150;if(enemy.hp<=0)killAirEnemy(enemy,ai,source);}}for(let oi=obstacles.length-1;oi>=0;oi--){const obstacle=obstacles[oi];if(obstacle.kind!=='gravity'&&Math.hypot(obstacle.x-item.x,obstacle.y-item.y)<radius+obstacle.r)destroyObstacle(oi,source);}}
function updateRocketWeapons(dt){bombCooldown=Math.max(0,bombCooldown-dt);missileCooldown=Math.max(0,missileCooldown-dt);const bombNow=input.bomb||input.keys.KeyB,missileNow=input.missile||input.keys.KeyM;if(bombNow&&!bombHeld)dropRocketBomb();if(missileNow&&!missileHeld)launchHomingMissile();bombHeld=bombNow;missileHeld=missileNow;for(let i=rocketBombs.length-1;i>=0;i--){const bomb=rocketBombs[i];bomb.x+=bomb.vx*dt;bomb.y+=bomb.vy*dt;bomb.vy+=.00074*dt;bomb.life-=dt;bomb.phase+=dt*.012;const obstacleHit=obstacles.some(o=>o.kind!=='gravity'&&Math.hypot(o.x-bomb.x,o.y-bomb.y)<o.r+9);if(obstacleHit||bomb.y>=groundY(bomb.x)-6||bomb.life<=0||bomb.x<0||bomb.x>worldW){bomb.y=Math.min(bomb.y,groundY(bomb.x)-6);explodeRocketWeapon(bomb,'bomb');rocketBombs.splice(i,1);}}for(let i=homingMissiles.length-1;i>=0;i--){const missile=homingMissiles[i];if(!airEnemies.includes(missile.target)&&!enemies.includes(missile.target)&&!obstacles.includes(missile.target))missile.target=findHomingTarget(missile.x,missile.y);if(missile.target){const desired=Math.atan2(missile.target.y-missile.y,missile.target.x-missile.x),delta=(desired-missile.angle+Math.PI*3)%TAU-Math.PI;missile.angle+=clamp(delta,-.0045*dt,.0045*dt);}missile.vx=Math.cos(missile.angle)*.5;missile.vy=Math.sin(missile.angle)*.5;missile.x+=missile.vx*dt;missile.y+=missile.vy*dt;missile.life-=dt;const directHit=missile.target&&Math.hypot(missile.target.x-missile.x,missile.target.y-missile.y)<(missile.target.size||missile.target.r||10)+10;if(directHit||missile.y>=groundY(missile.x)-5||missile.life<=0||missile.x<0||missile.x>worldW){explodeRocketWeapon(missile,'missile');homingMissiles.splice(i,1);}}}
function losePilot(){if(godModeEnabled()){if(pilot){pilot.health=pilotMaxHealth;pilot.invulnerable=600;}return;}if(gameOver)return;audio.noiseHit(.45,.18);haptic([40,30,60]);pilot=null;endMessage('PILOT LOST',`The creatures got you after ${kills} kill${kills===1?'':'s'}. Run: ${landings} landing${landings===1?'':'s'}.`);updateGroundUI();}
function overrunRocket(){if(godModeEnabled()){shipHull=shipMaxHull;shipShield=shipMaxShield;return;}if(gameOver)return;explode();endMessage('OVERRUN',`A creature breached the rocket. ${kills} kill${kills===1?'':'s'} · ${landings} landing${landings===1?'':'s'}.`);updateGroundUI();}
function updatePilot(dt){if(!pilot)return;const move=(input.right||input.keys.ArrowRight||input.keys.KeyD?1:0)-(input.left||input.keys.ArrowLeft||input.keys.KeyA?1:0);if(move)pilot.facing=Math.sign(move);pilot.vx=move*.18;pilot.x=clamp(pilot.x+pilot.vx*dt,18,worldW-18);const jump=input.jump||input.keys.Space||input.keys.ArrowUp||input.keys.KeyW;if(jump&&!pilotJumpHeld&&pilot.onGround){pilot.vy=pilotMaxHealth>3?-.57:-.48;pilot.onGround=false;audio.beep(330,.09,'triangle',.05);}pilotJumpHeld=jump;pilot.vy+=.00125*dt;pilot.y+=pilot.vy*dt;const gy=groundY(pilot.x)-16;if(pilot.y>=gy){pilot.y=gy;pilot.vy=0;pilot.onGround=true;}if((input.thrust||input.keys.KeyF||input.keys.KeyX)&&shootCooldown<=0)shootPilot();const throwNow=input.grenade||input.keys.KeyG;if(throwNow&&!grenadeHeld)throwGrenade();grenadeHeld=throwNow;const aimUp=input.keys.KeyQ,aimDown=input.keys.KeyE;if(aimUp&&!aimUpHeld)adjustAim(-.15);if(aimDown&&!aimDownHeld)adjustAim(.15);aimUpHeld=aimUp;aimDownHeld=aimDown;pilot.invulnerable=Math.max(0,pilot.invulnerable-dt);}
function updateGroundEncounter(dt){updateRocketWeapons(dt);shootCooldown=Math.max(0,shootCooldown-dt);grenadeCooldown=Math.max(0,grenadeCooldown-dt);if(ship.landed){groundElapsed+=dt;if(groundElapsed>=3000){enemySpawnCooldown-=dt;if(enemySpawnCooldown<=0&&enemies.length<groundEnemyCap()){spawnCreature();const base=Math.max(650,2100-kills*30)+rand(0,500);enemySpawnCooldown=Math.max(180,base/groundSpawnMultiplier());}}}else groundElapsed=0;if(pilot)updatePilot(dt);for(const bullet of bullets){bullet.x+=bullet.vx*dt;bullet.y+=bullet.vy*dt;bullet.life-=dt;}for(let bi=bullets.length-1;bi>=0;bi--){const bullet=bullets[bi];let hit=false;for(let ei=enemies.length-1;ei>=0;ei--){const enemy=enemies[ei];if(Math.abs(bullet.x-enemy.x)<enemy.size+5&&Math.abs(bullet.y-enemy.y)<enemy.size+12){const critical=bullet.y<enemy.y-enemy.size*.65;enemy.hp-=(critical?2:1)*(bullet.damage||1);enemy.hit=120;hit=true;if(enemy.hp<=0)killCreature(enemy,ei,'bullet',critical);break;}}if(hit||bullet.life<=0||bullet.x<0||bullet.x>worldW||bullet.y<0||bullet.y>worldH)bullets.splice(bi,1);}for(let gi=grenades.length-1;gi>=0;gi--){const grenade=grenades[gi];grenade.x+=grenade.vx*dt;grenade.y+=grenade.vy*dt;grenade.vy+=.00072*dt;grenade.life-=dt;grenade.phase+=dt*.02;const gy=groundY(grenade.x)-5;if(grenade.y>=gy){grenade.y=gy;if(Math.abs(grenade.vy)>.08&&grenade.bounces<2){grenade.vy*=-.38;grenade.vx*=.72;grenade.bounces++;audio.beep(170,.035,'square',.025);}else{grenade.vy=0;grenade.vx*=.9;}}if(grenade.life<=0||grenade.x<0||grenade.x>worldW){explodeGrenade(grenade);grenades.splice(gi,1);}}for(const enemy of enemies){enemy.hit=Math.max(0,enemy.hit-dt);if(ship.landed){const dir=Math.sign(ship.x-enemy.x)||1;enemy.x+=dir*enemy.speed*dt;enemy.y=groundY(enemy.x)-enemy.size;}if(pilot&&pilot.invulnerable<=0&&Math.abs(enemy.x-pilot.x)<enemy.size+9&&Math.abs(enemy.y-pilot.y)<enemy.size+14){if(godModeEnabled()){pilot.health=pilotMaxHealth;pilot.invulnerable=250;}else{pilot.health--;pilot.invulnerable=950;}camera.shake=7;audio.noiseHit(.18,.09);haptic(28);if(pilot.health<=0){losePilot();return;}}if(ship.landed&&Math.abs(enemy.x-ship.x)<enemy.size+19){overrunRocket();return;}}enemies=enemies.filter(enemy=>enemy.boss||ship.landed||Math.abs(enemy.x-ship.x)<900);for(const burst of fuelBursts){burst.y-=.025*dt;burst.life-=dt;}fuelBursts=fuelBursts.filter(b=>b.life>0);if(performance.now()-lastKillAt>2200)combatCombo=0;updateGroundUI();}
function updateParticles(dt){particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.vy+=p.g*dt;});particles=particles.filter(p=>p.life>0);}

function applyAssist(c,dt,manualSteering){ const s=getSettings(); assistThrust=false; if(s.assistMode==='off') return; const frame=dt/16.67; const angleAssistAllowed=!manualSteering&&performance.now()>=manualSteerUntil; const nearest=getNextPad()||pads[0]; const padCx=nearest.x+nearest.w/2; const alt=groundY(ship.x)-ship.y; if((s.assistMode==='level'||s.assistMode==='training')&&angleAssistAllowed){ ship.angle*=Math.pow(.965,frame); ship.vx*=Math.pow(.997,frame); }
  if(s.assistMode==='landing'||s.assistMode==='training'){
    const dx=padCx-ship.x; ship.vx += clamp(dx*.00025,-.067,.067)*frame; if(alt<450 && ship.vy>c.safeV*.78 && (godModeEnabled()||ship.fuel>0)) assistThrust=true; if(angleAssistAllowed) ship.angle=lerp(ship.angle, clamp(-ship.vx*.55 + dx*.0009,-.32,.32), clamp(.018*frame,0,1));
  }
  if(s.assistMode==='training'){ ship.vy*=Math.pow(.999,frame); }
}
function update(dt){ if(!running||paused||gameOver) return; const s=getSettings(), c=CFG[s.difficulty]; if(godModeEnabled())godModeUsedThisRun=true; const step=dt/16.67; windPhase+=dt*.006; const wind=Math.sin(windPhase)*c.wind*dt; input.tilt=clamp(input.tilt,-1,1);
  updateGroundEncounter(dt);if(gameOver){updateParticles(dt);return;}updateObstacles(dt,step);if(gameOver){updateParticles(dt);return;}updateAirCombat(dt);if(gameOver){updateParticles(dt);return;}
  if(pilot){updateParticles(dt);positionCamera(pilot,W>H?.52:.50);camera.shake*=.9;audio.setThrust(false);updateHUD(c);return;}
  let rot=0; if(input.left||input.keys.ArrowLeft||input.keys.KeyA) rot-=1; if(input.right||input.keys.ArrowRight||input.keys.KeyD) rot+=1; if(['tilt','hybrid'].includes(s.controlMode)) rot+=input.tilt*(s.controlMode==='tilt'?1.35:.95); const manualSteering=Math.abs(rot)>.06; if(manualSteering) manualSteerUntil=performance.now()+450; ship.angle += rot*.050*step; ship.angle=clamp(ship.angle,-Math.PI*.82,Math.PI*.82);
  const manualThrusting=(input.thrust||input.keys.Space||input.keys.ArrowUp||input.keys.KeyW)&&(godModeEnabled()||s.fuelMode==='unlimited'||ship.fuel>0), thrustLevel=THRUST_LEVELS[thrustMode].power;
  if(ship.landed&&!manualThrusting){assistThrust=false;ship.power=lerp(ship.power,0,.28);ship.vx=0;ship.vy=0;audio.setThrust(false);updateParticles(dt);positionCamera(ship,.52);camera.shake*=.9;updateHUD(c);return;}
  if(ship.landed&&manualThrusting){ship.landed=false;ship.y-=3;ship.trail=[];groundElapsed=0;}
  applyAssist(c,dt,manualSteering);
  const thrusting=(manualThrusting||assistThrust)&&(godModeEnabled()||s.fuelMode==='unlimited'||ship.fuel>0);
  const power=thrusting?thrustLevel*engineBoost:0; ship.power=lerp(ship.power,power,.18); if(thrusting){ ship.vx += Math.sin(ship.angle)*c.thrust*power*step; ship.vy -= Math.cos(ship.angle)*c.thrust*power*step; if(s.fuelMode==='limited'&&!godModeEnabled()) ship.fuel=Math.max(0,ship.fuel-.018*dt*power*fuelEfficiency); ship.heat=1; spawnThrust(dt); }
  ship.vy += c.g*step; ship.vx += wind; ship.vx*=Math.pow(.998,dt); ship.vy*=Math.pow(.999,dt); ship.x+=ship.vx*step; ship.y+=ship.vy*step; ship.x=clamp(ship.x,20,worldW-20); if(ship.y<20){ship.y=20;ship.vy=0;}
  updateParticles(dt);checkLanding(c);positionCamera(ship,shipCameraAnchor());camera.shake*=.9; audio.setThrust(thrusting,ship.power); ship.heat*=.94; updateHUD(c); }
function spawnThrust(dt){ const n=getSettings().graphicsMode==='battery'?1:3; for(let i=0;i<n;i++){ const a=ship.angle+Math.PI+rand(-.24,.24); particles.push({x:ship.x-Math.sin(ship.angle)*18+rand(-3,3),y:ship.y+Math.cos(ship.angle)*20+rand(-3,3),vx:Math.sin(a)*rand(.04,.11),vy:-Math.cos(a)*rand(.04,.11),life:rand(260,520),r:rand(2,6),g:.00008,color:Math.random()<.5?'#ffb23d':'#ff2f8f'}); } }
function checkLanding(c){
  if(ship.landed)return;
  const gy=groundY(ship.x);if(ship.y+24<gy)return;ship.y=gy-24;
  const s=getSettings(),pad=pads.find(p=>ship.x>p.x&&ship.x<p.x+p.w&&Math.abs(gy-(p.y+5))<18),upright=Math.abs(ship.angle)<.22,slowV=Math.abs(ship.vy)<c.safeV,slowH=Math.abs(ship.vx)<c.safeH;
  if(pad&&(godModeEnabled()||(upright&&slowV&&slowH))){
    const touchdownV=Math.abs(ship.vy);
    ship.landed=true;ship.vx=0;ship.vy=0;ship.angle=0;ship.power=0;ship.trail=[];groundElapsed=0;enemySpawnCooldown=0;audio.setThrust(false);
    if(pad.used){audio.beep(420,.12,'triangle',.07);return;}
    pad.used=true;streak++;landings++;grenadeAmmo=Math.min(5,grenadeAmmo+1);bombAmmo=Math.min(bombCapacity,bombAmmo+1);if(shipMaxShield)shipShield=shipMaxShield;if(shipMaxHull>3)shipHull=Math.min(shipMaxHull,shipHull+1);
    const elapsed=(performance.now()-missionStart)/1000,timeBonus=s.missionType==='time'?Math.max(0,Math.round(2500-elapsed*55)):0,fuelBonus=Math.round(ship.fuel*8),softBonus=Math.round((c.safeV-touchdownV)*220);
    score+=pad.bonus+fuelBonus+Math.max(0,softBonus)+streak*150+timeBonus;localStorage.astraHighScore=Math.max(Number(localStorage.astraHighScore||0),score);audio.beep(659,.22,'triangle',.14);setTimeout(()=>audio.beep(987,.34,'triangle',.11),120);haptic([30,40,30]);
    const cycleComplete=pads.every(p=>p.used);
    if(s.missionType==='single'||(s.missionType==='time'&&cycleComplete)){endMessage('LANDED',`Perfect touchdown. ${landings} landing${landings===1?'':'s'}. Score ${score}. High ${localStorage.astraHighScore||score}.${timeBonus?' Time bonus '+timeBonus+'.':''}`);return;}
    if(s.missionType==='endless'&&cycleComplete){beginNextSector(pad,c);if(landings%5===0)showMilestoneReward(landings);}else{currentTargetPad=null;getNextPad();}
    updateHUD(c);return;
  }
  if(godModeEnabled()){ship.y=gy-28;ship.vy=-Math.max(.18,Math.abs(ship.vy)*.28);ship.vx*=.62;ship.angle*=.35;if(shipHitCooldown<=0){shipHitCooldown=450;fuelBursts.push({x:ship.x,y:ship.y-30,text:'GOD MODE · IMPACT IGNORED',life:850,color:'#ffd36b'});audio.beep(340,.07,'triangle',.035);}return;}
  if(s.missionType==='sandbox'){explode();ship.x=worldW*.18;ship.y=180;ship.vx=0;ship.vy=0;ship.angle=0;ship.fuel=c.fuel;gameOver=false;return;}
  explode();endMessage('CRASHED',`Run: ${landings} landing${landings===1?'':'s'} on this tank. Impact vertical ${ship.vy.toFixed(2)} / horizontal ${ship.vx.toFixed(2)} / angle ${(ship.angle*57.3).toFixed(0)}°`);
}
function explode(){ camera.shake=18; audio.noiseHit(.75,.32); audio.beep(65,.6,'sawtooth',.18); haptic([70,40,90]); for(let i=0;i<90;i++) particles.push({x:ship.x,y:ship.y,vx:rand(-.22,.22),vy:rand(-.28,.18),life:rand(500,1300),r:rand(2,8),g:.00018,color:Math.random()<.55?'#ff5c34':'#ffd36b'}); }
function endMessage(title,text){if(godModeEnabled()&&title!=='LANDED'){gameOver=false;shipHull=shipMaxHull;shipShield=shipMaxShield;if(pilot)pilot.health=pilotMaxHealth;pendingCheckpointRestore=false;els.msg.style.display='none';updateGroundUI();return false;}gameOver=true;audio.setThrust(false);els.msg.style.display='block';if(extraLives>0&&sectorCheckpoint&&getSettings().missionType==='endless'){extraLives--;pendingCheckpointRestore=true;els.msg.querySelector('h1').textContent='EXTRA LIFE READY';els.msg.querySelector('p').textContent=`${title}: ${text} Continue from landing ${sectorCheckpoint.landing}, the start of ${WORLD_THEMES[Math.min(sectorCheckpoint.padCycle,WORLD_THEMES.length-1)].name}. ${extraLives} extra ${extraLives===1?'life':'lives'} remaining.`;els.start.textContent='Continue Level';els.scoreEntry.classList.add('hidden');updateGroundUI();return;}pendingCheckpointRestore=false;els.msg.querySelector('h1').textContent=title;els.msg.querySelector('p').textContent=text;els.start.textContent='Fly Again';offerLeaderboardEntry();updateGroundUI();}
function updateHUD(c){ const alt=Math.max(0,groundY(ship.x)-ship.y-24); els.altitude.textContent=Math.round(alt); els.vspd.textContent=ship.vy.toFixed(2); els.hspd.textContent=ship.vx.toFixed(2); els.fuel.textContent=godModeEnabled()||getSettings().fuelMode==='unlimited'?'∞':Math.round(ship.fuel); els.landings.textContent=landings; els.score.textContent=score; const tr=document.getElementById('tiltReadout'); if(tr){ const s=getSettings(); tr.textContent=['tilt','hybrid'].includes(s.controlMode) ? (input.tiltSeen ? `TILT ${input.tilt.toFixed(2)}` : 'TILT waiting') : ''; } updateGroundUI(); }

function draw(){ requestAnimationFrame(draw); const now=performance.now(); const dt=clamp(now-last,0,33); last=now; update(dt); render(now); }
function render(t){ const s=getSettings(),theme=currentWorldTheme(); const shake=camera.shake?rand(-camera.shake,camera.shake):0; ctx.save(); ctx.clearRect(0,0,W,H); const grad=ctx.createLinearGradient(0,0,0,H); grad.addColorStop(0,theme.sky[0]);grad.addColorStop(.52,theme.sky[1]);grad.addColorStop(1,theme.sky[2]);ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);ctx.translate(-camera.x+shake,-camera.y+shake);
  drawWorldAtmosphere(t,theme,s);drawStars(t,s);drawPlanets(t,theme,s);drawTerrain(s,theme);drawPads(t,theme);drawObstacles(t);drawParticles();drawAirCombat(t,theme);drawShip(t,s);drawRocketWeapons(t);drawGroundGameplay(t);drawOverlay(s);ctx.restore();drawMiniMap(t);if(paused&&!resumeAfterReward)drawPause();}
function drawStars(t,s){ ctx.save(); for(const st of stars){ const px=st.x-camera.x*(.05+st.p*.08), py=st.y-camera.y*(.03+st.p*.06); if(px<camera.x-20||px>camera.x+W+20||py<camera.y-20||py>camera.y+H+20) continue; const tw=.55+.45*Math.sin(t*.002+st.tw); ctx.globalAlpha=st.p*tw; ctx.fillStyle=st.r>1.7?'#b8fbff':'#ffffff'; ctx.beginPath(); ctx.arc(px,py,st.r,0,TAU); ctx.fill(); } ctx.restore(); }
function drawWorldAtmosphere(t,theme,s){if(s.graphicsMode==='battery')return;ctx.save();const cx=camera.x+W*(.18+.05*Math.sin(padCycle)),cy=camera.y+H*.24,glow=ctx.createRadialGradient(cx,cy,0,cx,cy,W*.58);glow.addColorStop(0,theme.nebula+'55');glow.addColorStop(.45,theme.hot+'18');glow.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=glow;ctx.fillRect(camera.x-80,camera.y-80,W+160,H+160);ctx.globalAlpha=.13;ctx.strokeStyle=theme.accent;ctx.lineWidth=18;for(let i=0;i<3;i++){ctx.beginPath();let first=true;for(let x=-100;x<W+140;x+=40){const wx=camera.x+x,wy=camera.y+H*(.18+i*.11)+Math.sin(x*.008+t*.00025+i)*38;if(first)ctx.moveTo(wx,wy);else ctx.lineTo(wx,wy);first=false;}ctx.stroke();}ctx.restore();}
function drawPlanets(t,theme,s){if(s.graphicsMode==='battery')return;ctx.save();const px=camera.x+W*.78,py=camera.y+H*.16,r=64+padCycle*2;ctx.shadowColor=theme.planet;ctx.shadowBlur=42;const g=ctx.createRadialGradient(px-r*.35,py-r*.4,4,px,py,r);g.addColorStop(0,'#ffffff');g.addColorStop(.22,theme.planet);g.addColorStop(1,theme.sky[0]);ctx.fillStyle=g;ctx.globalAlpha=.78;ctx.beginPath();ctx.arc(px,py,r,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle=theme.accent+'88';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(px,py,r*1.55,r*.34,-.25+padCycle*.03,0,TAU);ctx.stroke();ctx.globalAlpha=.28;ctx.fillStyle=theme.hot;ctx.beginPath();ctx.arc(camera.x+W*.18,camera.y+H*.31,18+padCycle,0,TAU);ctx.fill();ctx.restore();}
function drawTerrain(s,theme){ctx.save();const deep=worldH+Math.max(800,H+220);ctx.globalAlpha=.22;ctx.fillStyle=theme.nebula;ctx.beginPath();ctx.moveTo(0,worldH*.69);for(let x=0;x<=worldW;x+=120)ctx.lineTo(x,worldH*.61+Math.sin(x*.004+padCycle)*80+((x/120+padCycle)%3)*25);ctx.lineTo(worldW,deep);ctx.lineTo(0,deep);ctx.fill();ctx.globalAlpha=1;ctx.beginPath();ctx.moveTo(terrain[0].x,deep);for(const p of terrain)ctx.lineTo(p.x,p.y);ctx.lineTo(worldW+200,deep);ctx.closePath();const g=ctx.createLinearGradient(0,worldH*.45,0,worldH);g.addColorStop(0,theme.ground[0]);g.addColorStop(1,theme.ground[1]);ctx.fillStyle=g;ctx.fill();ctx.strokeStyle=theme.accent;ctx.lineWidth=2.5;ctx.shadowColor=theme.accent;ctx.shadowBlur=s.graphicsMode==='battery'?0:14;ctx.beginPath();terrain.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.shadowBlur=0;if(s.graphicsMode==='ultra'){ctx.globalAlpha=.14;ctx.strokeStyle=theme.hot;for(let x=0;x<worldW;x+=76){ctx.beginPath();ctx.moveTo(x,groundY(x)+8);ctx.lineTo(x+38,groundY(x+38)+46);ctx.lineTo(x+76,groundY(x+76)+8);ctx.stroke();}}ctx.restore();}
function drawPads(t,theme){for(const p of pads){ctx.save();const pulse=.55+.45*Math.sin(t*.007+p.x),target=p===currentTargetPad,color=p.used?'#59ff91':target?'#ffd36b':theme.accent,cx=p.x+p.w/2;ctx.shadowColor=color;ctx.shadowBlur=(target?30:16)*pulse;const pg=ctx.createLinearGradient(p.x,p.y,p.x+p.w,p.y);pg.addColorStop(0,theme.hot+'44');pg.addColorStop(.5,color+'aa');pg.addColorStop(1,theme.hot+'44');ctx.fillStyle=pg;ctx.strokeStyle=color;ctx.lineWidth=3;ctx.fillRect(p.x,p.y,p.w,p.h);ctx.strokeRect(p.x,p.y,p.w,p.h);ctx.shadowBlur=0;ctx.strokeStyle=color+'55';for(let x=p.x+8;x<p.x+p.w;x+=14){ctx.beginPath();ctx.moveTo(x,p.y);ctx.lineTo(x-6,p.y+8);ctx.stroke();}if(!p.used){ctx.globalAlpha=.18+.12*pulse;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(cx-18,p.y);ctx.lineTo(cx,p.y-155);ctx.lineTo(cx+18,p.y);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=color;ctx.beginPath();ctx.arc(cx,p.y-28,18+8*pulse,0,TAU);ctx.stroke();}ctx.font='900 11px system-ui';ctx.fillStyle=color;ctx.textAlign='center';ctx.fillText(p.used?'✓ CLEARED':target?'▼ PRIMARY LANDING':'LANDING ZONE',cx,p.y-12);ctx.restore();}}
function drawObstacles(t){for(const obstacle of obstacles){ctx.save();ctx.translate(obstacle.x,obstacle.y);ctx.rotate(obstacle.kind==='asteroid'?obstacle.phase:0);if(obstacle.kind==='mine'){const pulse=.75+.25*Math.sin(t*.008+obstacle.phase);ctx.shadowColor='#ff3d91';ctx.shadowBlur=22*pulse;ctx.strokeStyle='#ffd36b';ctx.fillStyle='#701a62';ctx.lineWidth=3;for(let i=0;i<8;i++){ctx.rotate(TAU/8);ctx.beginPath();ctx.moveTo(obstacle.r*.72,0);ctx.lineTo(obstacle.r+12,0);ctx.stroke();}ctx.beginPath();ctx.arc(0,0,obstacle.r,0,TAU);ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(0,0,4,0,TAU);ctx.fill();}else if(obstacle.kind==='asteroid'){ctx.shadowColor='#ff8a38';ctx.shadowBlur=14;ctx.fillStyle='#6d4a46';ctx.strokeStyle='#ffd36b';ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<9;i++){const a=i/9*TAU,r=obstacle.r*(.72+.28*Math.sin(i*4.7+obstacle.phase));const x=Math.cos(a)*r,y=Math.sin(a)*r;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='rgba(20,8,12,.5)';ctx.beginPath();ctx.arc(-6,-4,5,0,TAU);ctx.arc(7,6,4,0,TAU);ctx.fill();}else{const pulse=.65+.35*Math.sin(t*.006+obstacle.phase);ctx.shadowColor='#b87cff';ctx.shadowBlur=28;ctx.strokeStyle=`rgba(184,124,255,${pulse})`;ctx.lineWidth=4;for(let r=obstacle.r*.55;r<=obstacle.r*1.45;r+=12){ctx.beginPath();ctx.arc(0,0,r,obstacle.phase+r*.03,obstacle.phase+r*.03+Math.PI*1.45);ctx.stroke();}ctx.fillStyle='rgba(30,3,60,.72)';ctx.beginPath();ctx.arc(0,0,obstacle.r*.48,0,TAU);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(0,0,3,0,TAU);ctx.fill();}ctx.restore();}}
function drawParticles(){ ctx.save(); for(const p of particles){ ctx.globalAlpha=clamp(p.life/700,0,1); ctx.fillStyle=p.color; ctx.shadowColor=p.color; ctx.shadowBlur=12; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,TAU); ctx.fill(); } ctx.restore(); }
function drawAirCombat(t,theme){ctx.save();for(const enemy of airEnemies){ctx.save();ctx.translate(enemy.x,enemy.y);ctx.rotate(Math.sin(enemy.phase)*.12);const pulse=.75+.25*Math.sin(t*.01+enemy.phase);ctx.shadowColor=enemy.color;ctx.shadowBlur=enemy.boss?34:18;if(enemy.boss){ctx.strokeStyle=theme.hot;ctx.lineWidth=3;for(let r=enemy.size+12;r<enemy.size+34;r+=10){ctx.globalAlpha=.32;ctx.beginPath();ctx.arc(0,0,r,enemy.phase+r*.03,enemy.phase+r*.03+Math.PI*1.45);ctx.stroke();}ctx.globalAlpha=1;}const g=ctx.createLinearGradient(-enemy.size,0,enemy.size,0);g.addColorStop(0,theme.sky[0]);g.addColorStop(.45,enemy.hit?'#ffffff':enemy.color);g.addColorStop(1,theme.hot);ctx.fillStyle=g;ctx.strokeStyle='#eaffff';ctx.lineWidth=enemy.boss?3:2;ctx.beginPath();if(enemy.kind==='scout'){ctx.moveTo(enemy.size,0);ctx.lineTo(-enemy.size,-enemy.size*.62);ctx.lineTo(-enemy.size*.45,0);ctx.lineTo(-enemy.size,enemy.size*.62);}else if(enemy.kind==='fighter'){ctx.moveTo(enemy.size*1.25,0);ctx.lineTo(-enemy.size,-enemy.size*.82);ctx.lineTo(-enemy.size*.52,0);ctx.lineTo(-enemy.size,enemy.size*.82);}else{ctx.moveTo(enemy.size*1.15,0);ctx.lineTo(enemy.size*.3,-enemy.size*.62);ctx.lineTo(-enemy.size*.85,-enemy.size*.48);ctx.lineTo(-enemy.size,0);ctx.lineTo(-enemy.size*.85,enemy.size*.48);ctx.lineTo(enemy.size*.3,enemy.size*.62);}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#07101c';ctx.beginPath();ctx.ellipse(enemy.size*.2,0,enemy.size*.32,enemy.size*.22,0,0,TAU);ctx.fill();ctx.fillStyle=theme.accent;ctx.beginPath();ctx.arc(enemy.size*.27,0,Math.max(2,enemy.size*.1)*pulse,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='rgba(0,0,0,.72)';ctx.fillRect(-enemy.size,-enemy.size-16,enemy.size*2,5);ctx.fillStyle=enemy.boss?'#ffd36b':'#59ff91';ctx.fillRect(-enemy.size,-enemy.size-16,enemy.size*2*clamp(enemy.hp/enemy.maxHp,0,1),5);if(enemy.boss){ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='900 11px system-ui';ctx.fillText(`⚠ ${enemy.name}`,0,-enemy.size-23);}ctx.restore();}ctx.lineCap='round';for(const shot of rocketShots){ctx.strokeStyle=shot.source==='drone'?'#7cffb2':(cannonDamage>=3||godModeEnabled())?'#ffffff':'#72c7ff';ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=16;ctx.lineWidth=(cannonDamage>=3||godModeEnabled())?5:3;ctx.beginPath();ctx.moveTo(shot.x-shot.vx*22,shot.y-shot.vy*22);ctx.lineTo(shot.x,shot.y);ctx.stroke();}for(const shot of enemyShots){ctx.strokeStyle=shot.color;ctx.shadowColor=shot.color;ctx.shadowBlur=14;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(shot.x-shot.vx*16,shot.y-shot.vy*16);ctx.lineTo(shot.x,shot.y);ctx.stroke();}if(guardianDrone&&!pilot){const a=t*.0022,dx=ship.x+Math.cos(a)*52,dy=ship.y+Math.sin(a)*24;ctx.translate(dx,dy);ctx.rotate(a+Math.PI/2);ctx.shadowColor='#63ffcf';ctx.shadowBlur=22;ctx.fillStyle='#152d43';ctx.strokeStyle='#8fffe1';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(13,7);ctx.lineTo(0,3);ctx.lineTo(-13,7);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(0,0,3,0,TAU);ctx.fill();}ctx.restore();}
function drawShip(t,s){ if(gameOver&&particles.length) return; ctx.save();
  ctx.globalAlpha=1; ctx.translate(ship.x,ship.y); ctx.rotate(ship.angle);if(shipShield>0){const pulse=.82+.18*Math.sin(t*.012);ctx.strokeStyle=`rgba(125,249,255,${.5*pulse})`;ctx.fillStyle='rgba(78,160,255,.08)';ctx.lineWidth=3;ctx.shadowColor='#7df9ff';ctx.shadowBlur=24;ctx.beginPath();ctx.arc(0,0,43+shipShield*2,0,TAU);ctx.fill();ctx.stroke();ctx.shadowBlur=0;} if(ship.power>.05){ const flame=30+ship.power*38+Math.sin(t*.04)*8; const gr=ctx.createLinearGradient(0,18,0,18+flame); gr.addColorStop(0,'#fff7a8'); gr.addColorStop(.35,'#ff8a38'); gr.addColorStop(1,'rgba(255,30,122,0)'); ctx.fillStyle=gr; ctx.beginPath(); ctx.moveTo(-9,19); ctx.lineTo(0,18+flame); ctx.lineTo(9,19); ctx.closePath(); ctx.fill(); }
  drawShipBody(false); ctx.restore(); }
