async function enableTilt(){ audio.resume(); input.tiltBase=null; try{ if(!window.isSecureContext && location.hostname!=='localhost' && location.hostname!=='127.0.0.1'){ throw new Error('iPhone motion needs HTTPS or localhost'); } if(typeof DeviceOrientationEvent==='undefined') throw new Error('DeviceOrientation unavailable'); if(typeof DeviceOrientationEvent.requestPermission==='function'){ const res=await DeviceOrientationEvent.requestPermission(); if(res!=='granted') throw new Error('permission denied'); } opts.controlMode.value=opts.controlMode.value==='touch'?'hybrid':opts.controlMode.value; saveSettings(); updateTouchVisibility(); els.tilt.textContent='Tilt Enabled — move phone'; audio.beep(880,.18,'triangle',.12); }catch(e){ els.tilt.textContent='Tilt needs HTTPS — use buttons'; audio.beep(180,.25,'sawtooth',.1); } }
function handleTilt(gamma,beta,source='orientation'){ if(gamma==null && beta==null) return; const raw=Number.isFinite(gamma)?gamma:(Number(beta)||0); if(input.tiltSource!==source){input.tiltSource=source;input.tiltBase=null;} if(input.tiltBase===null) input.tiltBase=raw; input.tiltRaw=raw; input.tiltSeen=true; input.tilt=clamp((raw-input.tiltBase)/14,-1,1); }
let lastOrientationAt=0;
addEventListener('deviceorientation',e=>{lastOrientationAt=performance.now();handleTilt(e.gamma,e.beta,'orientation');},{passive:true});
addEventListener('devicemotion',e=>{ const a=e.accelerationIncludingGravity; if(a&&performance.now()-lastOrientationAt>750) handleTilt(a.x*5,a.y*5,'motion'); },{passive:true});
window.astraTiltTest=(raw)=>{handleTilt(raw,0,'test'); return {tilt:input.tilt, raw:input.tiltRaw, base:input.tiltBase, source:input.tiltSource};};
const controlPointers={left:new Set(),right:new Set(),thrust:new Set(),jump:new Set(),grenade:new Set(),bomb:new Set(),missile:new Set(),cannon:new Set()};
function syncControl(name){ const active=controlPointers[name].size>0; input[name]=active; els[name].classList.toggle('active',active); }
function releaseControlToken(token){ for(const name of Object.keys(controlPointers)){ if(controlPointers[name].delete(token)) syncControl(name); } }
function clearAllControls(){ for(const name of Object.keys(controlPointers)){controlPointers[name].clear();syncControl(name);} input.keys={}; audio?.setThrust(false); }
['left','right','thrust','jump','grenade','bomb','missile','cannon'].forEach(name=>{ const el=els[name];
  el.addEventListener('touchstart',ev=>{ev.preventDefault();audio.resume();for(const touch of ev.changedTouches)controlPointers[name].add(`t:${touch.identifier}`);syncControl(name);},{passive:false});
  el.addEventListener('pointerdown',ev=>{if(ev.pointerType==='touch')return;ev.preventDefault();audio.resume();controlPointers[name].add(`p:${ev.pointerId}`);syncControl(name);try{el.setPointerCapture(ev.pointerId);}catch{}});
  el.addEventListener('pointerup',ev=>releaseControlToken(`p:${ev.pointerId}`));
  el.addEventListener('pointercancel',ev=>releaseControlToken(`p:${ev.pointerId}`));
  el.addEventListener('lostpointercapture',ev=>releaseControlToken(`p:${ev.pointerId}`));
  for(const eventName of ['contextmenu','selectstart','dragstart']) el.addEventListener(eventName,ev=>ev.preventDefault());
});
for(const eventName of ['touchend','touchcancel']) document.addEventListener(eventName,ev=>{for(const touch of ev.changedTouches)releaseControlToken(`t:${touch.identifier}`);},{capture:true,passive:true});
for(const eventName of ['pointerup','pointercancel']) addEventListener(eventName,ev=>releaseControlToken(`p:${ev.pointerId}`),{capture:true});
